# Based on my analysis:
# 1. Background = most common color
# 2. Find the unique non-background, non-singleton pattern (stamp)
# 3. Find all positions of marker color (color different from background and stamp)
# 4. Replace each marker with the stamp, aligned so stamp index 2 (value 2) is at marker position

# For demo:
# - Background: 8
# - Stamp: [6, 2, 2, 6, 6]
# - Marker: 9

def transform(grid):
    # Find background (most common color)
    from collections import Counter
    counts = Counter()
    for row in grid:
        counts.update(row)
    background = max(counts.keys(), key=lambda c: counts[c])

    # Find non-background colors
    non_bg = [c for c in counts if c != background]

    # Find marker color (singletons scattered) and stamp pattern
    # The pattern appears first in the grid and forms a contiguous line
    # The markers appear later and are single cells

    # Find all non-background cells
    cells = [(r, c, grid[r][c]) for r in range(len(grid)) for c in range(len(grid[0]))]

    # Find the pattern - look for horizontal or vertical runs of same color
    # The pattern should be longer than 1 and different from markers
    max_run = 0
    pattern = None

    # Check horizontal runs
    for r in range(len(grid)):
        for c in range(len(grid[0]) - max_run):
            color = grid[r][c]
            if color == background:
                continue
            run = 1
            for dc in range(1, len(grid[0]) - c):
                if grid[r][c+dc] == color:
                    run += 1
                else:
                    break
            if run >= max_run:
                max_run = run
                pattern = (r, c, color, run)  # row, col, color, run_length

    # Check vertical runs
    for c in range(len(grid[0]) - max_run):
        for r in range(len(grid) - max_run):
            color = grid[r][c]
            if color == background:
                continue
            run = 1
            for dr in range(1, len(grid) - r):
                if grid[r+dr][c] == color:
                    run += 1
                else:
                    break
            if run >= max_run and run > 1:
                max_run = run
                pattern = (r, c, color, run)

    # Now find markers (single non-background cells not part of pattern)
    marker_color = None
    marker_positions = []

    pattern_r, pattern_c, pattern_color, pattern_run = pattern

    # Check which non-backgound colors are markers (single cells)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            color = grid[r][c]
            if color == background:
                continue
            if color == pattern_color:
                continue
            if count_matches(grid, r, c, color) == 1:
                if marker_color is None:
                    marker_color = color
                marker_positions.append((r, c))

    def count_matches(grid, r, c, color):
        count = 0
        for nr in range(len(grid)):
            for nc in range(len(grid[0])):
                if grid[nr][nc] == color:
                    count += 1
        return count

    # Find the stamp pattern - it's the non-background non-marker color pattern
    # For demo, pattern_color is 6-2-2-6-6 (multiple colors!)

    # Actually the pattern has MULTIPLE colors
    # Let me just grab the full pattern
    for r in range(len(grid)):
        for c in range(len(grid[0]) - 4):
            window = []
            cols = [grid[r][c+i] for i in range(5)]
            if all(v != background for v in cols):
                window = cols
                if window.count(pattern_color) > 0:
                    # This could be the pattern
                    pass

    # Find pattern from the known pattern row
    # For demo, it's row 15, but I need to find it dynamically

    # Let me be more careful: find the longest horizontal run that's NOT a marker
    # For demo, the pattern is [6, 2, 2, 6, 6] which is a horizontal run of 5 non-background cells

    # Find all horizontal runs of non-background
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == background:
                continue
            run_start = c
            run_end = c
            while run_end < len(grid[0]) and grid[r][run_end] != background:
                run_end += 1
            run = list(grid[r][run_start:run_end])
            # Check if this run has multiple colors or interesting structure
            if len(run) >= 3 and len(set(run)) > 1:
                # This is the stamp pattern!
                return run, marker_color if marker_color else None, marker_positions

    return None, None, []

